mapper.select:
SELECT o.id FROM orders o WHERE o.status IN ('STOCK_RESERVED', 'PAYMENT_PENDING') AND o.expires_at < NOW(6) AND NOT EXISTS ( SELECT 1 FROM payment p WHERE p.order_id = o.id AND p.status <> 'FAILED' ) AND o.is_deleted = false AND o.id > #{lastId}
AND o.expires_at >= #{startDate}
AND o.expires_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
ORDER BY o.id ASC LIMIT #{limit}

mapper.update:
UPDATE orders
SET status = 'EXPIRED', updated_at = NOW(6)
WHERE id = #{orderId}
  AND status = #{expectedStatus}

UPDATE stock
SET reserved_quantity = reserved_quantity - #{quantity}, updated_at = NOW(6)
WHERE product_id = #{productId}
  AND reserved_quantity >= #{quantity}
